// V18 species expansion. Run once with `node scripts/expand-species-v18.mjs`.
// Rows are deliberately compact: the generator expands them into the same
// validated Species record used by the original 13 dossiers.
import { mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';

const rows = [];

function add(row) {
  const [
    , sci, common, by, gk, clade, family, period, plabel, stage,
    older, younger, length, mass, region, rkey, context, habitat, related,
    summary, trait, preservation,
  ] = row.split('|');
  rows.push({
    slug: sci.split(' ')[0].toLowerCase(), sci, common, by, gk, clade, family, period, plabel, stage,
    age: [Number(older), Number(younger)], length, mass, region, rkey,
    context, habitat, related: related.split(','), summary, trait, preservation,
  });
}

