const confidenceNotes = {
  herrerasaurus:
    'Herrerasaurus is treated as a carnivore on the evidence of its dentition and jaw anatomy. Its position among early saurischians is debated, and some analyses place it outside Theropoda; the family assignment is therefore navigational rather than a resolved phylogenetic statement.',
  eoraptor:
    'Eoraptor is placed here in Saurischia incertae sedis because its position is unresolved: some analyses recover it as a basal theropod, others as a basal sauropodomorph. Its dentition mixes piercing and leaf-shaped teeth, so the omnivore label is an inference, not a direct observation.',
  mussaurus:
    'Adult Mussaurus reached roughly 6–8 m and 1.2–1.6 t; the first specimens were hatchlings about the size of a mouse, which explains the name. Adults are reconstructed as bipedal and hatchlings as quadrupedal. The Laguna Colorada Formation is Late Triassic (Norian); some older sources used a broader age range.',
  jobaria:
    'The Tiourarén Formation was originally interpreted as Early Cretaceous and is now read as Middle to Late Jurassic. This record uses a Middle Jurassic age (Bathonian–Oxfordian, about 167–161 Ma), following the revised stratigraphy; the original 1999 description was published as Cretaceous. Eusauropoda is a clade, not a family, and is used here as a navigational label for a sauropod whose family-level position is unresolved.',
  mamenchisaurus:
    'The Upper Shaximiao Formation has no reliable radiometric date. This record uses an Oxfordian age (about 161–155 Ma), consistent with dating of the underlying Lower Shaximiao beds; some treatments still place the Mamenchisaurus fauna in the Middle Jurassic.',
  leaellynasaura:
    'The holotype is a small individual about 1 m long, and the species is reconstructed here at 1–1.5 m and 3–5 kg. Larger referred materials exist, but the 2–3 m and 20–40 kg figures used in the earlier draft were not supported. Its family placement is unresolved, hence Ornithopoda incertae sedis.',
  rhabdodon:
    'Rhabdodon is a large rhabdodontid, but published adult lengths cluster at 4–6 m and masses near 250–500 kg; the earlier 6–7 m and 1–2 t figures were too large. The family Rhabdodontidae is well supported, while species-level referrals across Europe remain problematic.',
  minmi:
    'Minmi is a small Australian ankylosaur about 3 m long and 300 kg. Its family placement is unresolved: it has been recovered as a basal ankylosaurid, a nodosaurid, a stem ankylosaur and, in some analyses, outside Ankylosauria. The record therefore uses Ankylosauria incertae sedis.',
  huayangosaurus:
    'Huayangosaurus is the type of Huayangosauridae, a basal stegosaur family; placing it in Stegosauridae was too derived. The family is defined by its position outside Stegosauridae in several analyses.',
  gigantspinosaurus:
    'Gigantspinosaurus is usually placed in Huayangosauridae, but some analyses recover it as the most basal stegosaur outside the Huayangosauridae–Stegosauridae split. The family label is navigational.',
  miragaia:
    'The validity of Miragaia longicollum is disputed. A 2024 proposal treated it as a junior synonym of Dacentrurus armatus, while a 2025 redescription of the most complete specimen argued that it is distinct. The record keeps the species but does not resolve the argument.',
  microraptor:
    'Microraptor gui is treated here as a named species following authors who distinguish it from M. zhaoianus. Other analyses treat M. gui as a junior synonym of M. zhaoianus, so the species count and diagnosis are not settled. The four-winged plumage and gut contents are preserved; flight style remains debated.',
  yutyrannus:
    'Yutyrannus is placed in Proceratosauridae following analyses that recover it with Sinotyrannus and other crested tyrannosauroids. Other analyses place it among basal tyrannosauroids outside that family. The feathered integument is directly preserved; its exact phylogenetic position is not settled.',
  dilong:
    'Dilong is placed in Proceratosauridae following analyses that recover it with Guanlong and Proceratosaurus. Other analyses place it as a non-proceratosaurid basal tyrannosauroid, and some have recovered it outside Tyrannosauroidea. The filamentous integument is preserved; the family assignment is provisional.',
  plateosaurus:
    'Body-mass estimates for Plateosaurus range from about 0.6 t for a 6 m individual to about 4 t for the largest adults; the range here spans those published extremes rather than a single average.',
  dreadnoughtus:
    'Body mass is contested: limb-bone scaling produced about 59 t, while volumetric models give about 22–38 t. This record uses the volumetric range and treats the 59 t figure as an upper estimate, not a consensus value.',
  shunosaurus:
    'Eusauropoda is used here as a family-level navigational label; Shunosaurus has no universally agreed family, and its position among basal eusauropods is what the label records.',
  turiasaurus:
    'Turiasauria is a clade, not a formal family; the label is used for navigation because Turiasaurus is not assigned to a stable family in the cited literature.',
  sinosauropteryx:
    'Sinosauropteryx is placed in Compsognathidae here, but some analyses recover it in Sinosauropterygidae or outside Compsognathidae. The filamentous integument and gut contents are directly preserved; the family assignment is not settled.',
  anchiornis:
    'Anchiornis is placed in Anchiornithidae here, following analyses that separate it from Troodontidae. Other analyses recover it as a troodontid, so the family assignment is provisional.',
  ouranosaurus:
    'Ouranosaurus is a styracosternan iguanodontian; some analyses place it among hadrosauroids rather than in Iguanodontidae. The family label is therefore provisional.',
  muttaburrasaurus:
    'Muttaburrasaurus is often recovered as a rhabdodontomorph rather than a member of Iguanodontidae. The family label is provisional and the genus is not the basis for a stable family assignment here.',
  polacanthus:
    'Polacanthus is placed in Nodosauridae here, following broad treatments; some analyses use Polacanthidae for it and close relatives. The family label is provisional.',};

const defaultConfidenceNote =
  'This is a database record for a named species, not a complete monograph. The diagnosis, age range and body-size estimates depend on the cited literature and the completeness of the hypodigm. Soft-tissue anatomy and behaviour are not preserved unless explicitly stated.';

const herbivoreFamilies = new Set(['Therizinosauridae']);
const omnivoreFamilies = new Set(['Ornithomimidae', 'Deinocheiridae', 'Oviraptoridae', 'Caenagnathidae']);
function dietFor(item) {
  if (item.slug === 'herrerasaurus') return { diet: 'carnivore', label: 'Carnivore' };
  if (item.slug === 'eoraptor') return { diet: 'omnivore', label: 'Omnivore · debated' };
  if (item.slug === 'heterodontosaurus') return { diet: 'herbivore', label: 'Herbivore · debated' };
  if (herbivoreFamilies.has(item.family)) return { diet: 'herbivore', label: 'Herbivore · inferred' };
  if (omnivoreFamilies.has(item.family)) return { diet: 'omnivore', label: 'Omnivore · inferred' };
  if (item.gk === 'Theropoda') return { diet: 'carnivore', label: 'Carnivore' };
  return { diet: 'herbivore', label: 'Herbivore' };
}

const bipedalOrnithopods = new Set(['hypsilophodon', 'orodromeus', 'leaellynasaura', 'dryosaurus']);
const bipedalOrnithischians = new Set(['pachycephalosaurus', 'heterodontosaurus', 'lesothosaurus', 'kulindadromeus']);
const facultativeOrnithischians = new Set(['psittacosaurus']);
const facultativeOrnithopods = new Set([
  'iguanodon',
  'tenontosaurus',
  'camptosaurus',
  'rhabdodon',
  'muttaburrasaurus',
  'ouranosaurus',
]);

function locomotionFor(item) {
  if (item.slug === 'herrerasaurus' || item.slug === 'eoraptor') return 'Bipedal';
  if (item.slug === 'heterodontosaurus') return 'Facultatively bipedal; quadrupedal';
  if (item.slug === 'mussaurus') return 'Bipedal as an adult; quadrupedal as a hatchling';
  if (item.slug === 'plateosaurus' || item.slug === 'massospondylus') {
    return 'Facultatively bipedal; quadrupedal';
  }
  if (bipedalOrnithopods.has(item.slug) || bipedalOrnithischians.has(item.slug)) return 'Bipedal';
  if (facultativeOrnithopods.has(item.slug) || facultativeOrnithischians.has(item.slug)) {
    return 'Facultatively bipedal; quadrupedal';
  }
  if (item.gk === 'Theropoda') return 'Bipedal';
  if (item.gk === 'Sauropodomorpha') return 'Quadrupedal';
  if (item.family === 'Hadrosauridae') return 'Facultatively bipedal; quadrupedal';
  return 'Quadrupedal';
}

function taxonomyFor(item) {
  const rows = [
    { rank: 'Kingdom', value: 'Animalia' },
    { rank: 'Phylum', value: 'Chordata' },
    { rank: 'Clade', value: 'Dinosauria' },
  ];
  if (item.gk === 'Theropoda' || item.gk === 'Sauropodomorpha' || item.gk === 'Saurischia') {
    rows.push({ rank: 'Clade', value: 'Saurischia' });
  }
  if (item.gk === 'Theropoda') rows.push({ rank: 'Clade', value: 'Theropoda' });
  if (item.gk === 'Sauropodomorpha') rows.push({ rank: 'Clade', value: 'Sauropodomorpha' });
  if (item.gk === 'Ornithischia') rows.push({ rank: 'Clade', value: 'Ornithischia' });
  if (item.clade && item.clade !== item.gk) rows.push({ rank: 'Clade', value: item.clade });
  if (item.family && item.family !== item.clade) rows.push({ rank: 'Family', value: item.family });
  const [genus, epithet] = item.sci.split(' ');
  rows.push({ rank: 'Genus', value: genus });
  rows.push({ rank: 'Species', value: `${genus[0]}. ${epithet}` });
  return rows;
}

const outputDir = path.join('src', 'data', 'species');
await mkdir(outputDir, { recursive: true });

const written = [];
for (let i = 0; i < rows.length; i += 1) {
  const item = rows[i];
  const [genus, epithet] = item.sci.split(' ');
  const diet = dietFor(item);
  const locomotion = locomotionFor(item);
  const ageLabel = `≈${item.age[0]}–${item.age[1]} Ma`;
  const primaryRef =
    item.slug === 'jobaria' || item.slug === 'nigersaurus' ? 'sereno1999' : `primary-${item.slug}`;
  const refs = [primaryRef, 'pbdb', 'paul2016'];
  const recordRefs =
    item.slug === 'jobaria' ? [primaryRef, 'rauhut2009', 'pbdb', 'paul2016'] : refs;
  const record = {
    slug: item.slug,
    accession: `MZ-${String(i + 14).padStart(3, '0')}`,
    scientificName: item.sci,
    commonName: item.common,
    genus,
    epithet,
    status: 'Extinct',
    namedBy: item.by,
    group: `${item.gk} · ${item.family}`,
    groupKey: item.gk,
    period: item.period,
    periodLabel: item.plabel,
    stage: item.stage,
    ageMa: item.age,
    ageLabel,
    region: [item.region],
    regionKeys: [item.rkey],
    diet: diet.diet,
    dietLabel: diet.label,
    dietEvidence: {
      body: `Diet is inferred from the preserved skull, dentition and comparative anatomy. Direct gut contents are known for only a minority of dinosaurs; where this record does not describe them, the classification is an interpretation, not an observation.`,
      evidence: 'inference',
      refs,
    },
    length: item.length,
    mass: item.mass,
    sizeNote: 'Length and mass are published estimates, not measurements of a complete individual. The hypodigm is incomplete; treat these figures as ranges.',
    sizeRefs: ['paul2016'],
    featured: false,
    tagline: item.summary,
    summary: item.summary,
    taxonomy: taxonomyFor(item),
    discovery: {
      body: `Named by ${item.by}. The record is known from ${item.context}. ${item.preservation}`,
      evidence: 'fossil',
      refs: [primaryRef],
    },
    fossilEvidence: [
      {
        title: 'Preserved material',
        body: `${item.preservation} Completeness varies between specimens; missing elements are not reconstructed in this record.`,
        evidence: 'fossil',
        refs,
      },
      {
        title: 'Stratigraphic and geographic occurrence',
        body: `${item.context} records the species in the ${item.plabel}. The numeric range used here is ${ageLabel}, an occurrence estimate rather than a direct date on every specimen.`,
        evidence: 'fossil',
        refs: ['pbdb'],
      },
    ],
    anatomy: [
      {
        title: 'Preserved anatomy',
        body: `${item.trait}`,
        evidence: 'inference',
        refs,
      },
      {
        title: 'Body plan',
        body: `The species is reconstructed as ${locomotion.toLowerCase()}. This is a functional interpretation from the preserved skeleton, not a direct observation of a living animal.`,
        evidence: 'inference',
        refs,
      },
    ],
    behaviour: {
      body: `Direct evidence of behaviour is limited. ${diet.label.split(' · ')[0]} diet is inferred from anatomy. Where this record describes nesting, gut contents or bonebed associations, those are the specific evidence; general social, parental or migratory behaviour is not asserted. Habitat is reconstructed from the enclosing deposits: ${item.habitat.toLowerCase()}.`,
      evidence: 'inference',
      refs,
    },
    reconstruction: {
      body: `No life restoration is assigned to this database record. The species is known from ${item.preservation.toLowerCase()}. The plate and silhouette communicate an unillustrated record, not a reconstruction; preserved integument, where present, is described in the anatomy section, and the soft-tissue outline is otherwise not reconstructed.`,
      evidence: 'reconstruction',
      refs,
    },
    references: recordRefs,
    related: item.related.filter((slug) => slug !== item.slug),
    confidenceNote: confidenceNotes[item.slug] ?? defaultConfidenceNote,
    updated: '2026-11-16',
    added: '2026-11-16',
    locomotion,
    habitat: item.habitat,
    ancientContext: item.context,
    locality: [item.context],
  };
  await writeFile(path.join(outputDir, `${item.slug}.json`), `${JSON.stringify(record, null, 2)}\n`);
  written.push(record);
}

console.log(`Wrote ${written.length} species records to ${outputDir}.`);
if (written.length !== 100) {
  console.error(`Expected 100 records, got ${written.length}.`);
  process.exitCode = 1;
}

